SELECT BREAK_TYPE, SUM(DIFF_USD) / 1e6 AS USD_M, FROM_ENTITY, TO_ENTITY, OWNER
FROM SDP_ASTRAZENECA_TEASER.PUBLIC.AZ_IC_BREAKS WHERE PERIOD = '2026-09'
GROUP BY ALL ORDER BY 2 DESC;

SELECT DOMAIN, COUNT(*) AS KEY_CONTROLS, AVG(IFF(TESTED, 1, 0)) AS TESTED_PCT,
       SUM(IFF(DEFICIENCY_OPEN, 1, 0)) AS OPEN_DEFICIENCIES
FROM SDP_ASTRAZENECA_TEASER.PUBLIC.AZ_CONTROLS GROUP BY 1 ORDER BY 2 DESC;

SELECT ADJUSTMENT_TYPE, SUM(AMOUNT_USD) / 1e6 AS USD_M
FROM SDP_ASTRAZENECA_TEASER.PUBLIC.AZ_CORE_BRIDGE WHERE QUARTER = '2026-Q3'
GROUP BY 1 ORDER BY 2 DESC;
